function plan(nodes, edges){
  const index = new Map();
  for(let i = 0; i < nodes.length; i++){
    if(!index.has(nodes[i])) index.set(nodes[i], i);
  }
  const adj = new Map();
  const indeg = new Map();
  for(const n of nodes){
    adj.set(n, []);
    indeg.set(n, 0);
  }

  // Deduplicate edges; ignore malformed or unknown-endpoint edges. Do not mutate inputs.
  const seen = new Set();
  for(const e of edges){
    if(!Array.isArray(e) || e.length < 2) continue;
    const from = e[0], to = e[1];
    if(!adj.has(from) || !adj.has(to)) continue;
    const k = from + '\u0000' + to;
    if(seen.has(k)) continue;
    seen.add(k);
    adj.get(from).push(to);
    indeg.set(to, indeg.get(to) + 1);
  }

  // Iterative DFS with colors and parent map to build an actual closed directed path.
  const color = new Map();
  const parent = new Map();
  let cycle = null;

  for(const start of nodes){
    if(color.get(start)) continue;
    color.set(start, 1);
    const stack = [[start, 0]];
    let found = false;
    while(stack.length){
      const top = stack[stack.length - 1];
      const u = top[0];
      const list = adj.get(u);
      if(top[1] < list.length){
        const v = list[top[1]++];
        if(color.get(v) === 1){
          // Back edge u -> v; build path v -> ... -> u -> v.
          const chain = [u];
          let cur = u;
          while(cur !== v){
            cur = parent.get(cur);
            chain.push(cur);
          }
          chain.reverse(); // now [v, ..., u]
          chain.push(v);   // close the cycle
          cycle = chain;
          found = true;
          break;
        }
        if(!color.get(v)){
          parent.set(v, u);
          color.set(v, 1);
          stack.push([v, 0]);
        }
      } else {
        color.set(u, 2);
        stack.pop();
      }
    }
    if(found) break;
  }

  if(cycle) return {order: [], cycle: cycle};

  // Kahn's algorithm choosing the ready node with the smallest original index.
  const ready = [];
  for(const n of nodes){
    if(indeg.get(n) === 0) ready.push(n);
  }
  const order = [];
  while(ready.length){
    let best = 0;
    for(let i = 1; i < ready.length; i++){
      if(index.get(ready[i]) < index.get(ready[best])) best = i;
    }
    const u = ready.splice(best, 1)[0];
    order.push(u);
    for(const v of adj.get(u)){
      const d = indeg.get(v) - 1;
      indeg.set(v, d);
      if(d === 0) ready.push(v);
    }
  }

  return {order: order, cycle: []};
}
